{"ASK_JOB_BEFORE","role=family_elder|tmp=seasoned|st=friendly,neutral",{"Thirty-one years at the feed store, I knew every farmer in three counties by their first name","Taught eighth-grade science, you wouldn't believe how many of them grew up to be nice people"}},
{"ASK_JOB_BEFORE","role=family_elder|tmp=seasoned|st=careful",{"I retired, and no, I'm not going to tell you where"}},
{"ASK_JOB_BEFORE","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"Insurance office in Louisville, nothing to brag about, I miss the coffee machine"}},
{"ASK_JOB_BEFORE","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|world=vehicle,road",{"I drove a delivery van, knew every back road in the county - funny what you end up good at"}},
{"ASK_JOB_BEFORE","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=careful",{"Does it matter? I work at staying alive now"}},
{"ASK_JOB_BEFORE","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=trees",{"Hunting guide up in the hills, strangers pay good money to be quiet in the woods"}},
